#define main gen_font_generator_main
#include "gen_font_golden.cpp"
#undef main

using namespace fontgen;

// The bench corpus: a 1024x64 16-bit A1R5G5B5 strike with 64 glyphs of
// 12 columns at a 16-column pitch (the scale of the other Phase 2
// benches; 131,072 image bytes).
#define BENCH_WIDTH 1024
#define BENCH_HEIGHT 64
#define BENCH_GLYPHS 64

// The final-state checksum over the loaded font's observable fields
// (the same walk the Rust bench drives): the verdict-independent table
// bits, the uchar tables, the VHeight bits and the packed page bytes.
static uint64_t font_checksum(const Font3DDataClass &font)
{
        uint64_t sum = 0;
        for (int c = 0; c < 256; c++)
        {
                sum = sum * 31 + fbits(font.UOffsetTable[c]);
                sum = sum * 31 + fbits(font.VOffsetTable[c]);
                sum = sum * 31 + fbits(font.UWidthTable[c]);
                sum = sum * 31 + (uint64_t)font.CharWidthTable[c];
        }
        sum = sum * 31 + fbits(font.VHeight);
        sum = sum * 31 + (uint64_t)font.CharHeight;
        if (const SurfaceClass *packed = font.Texture)
        {
                sum = sum * 31 + packed->Width;
                sum = sum * 31 + packed->Height;
                sum = sum * 31 + sum31(packed->Bytes.data(), packed->Bytes.size());
        }
        return sum;
}

// The corpus bytes (the same formula the Rust bench builds).
static std::vector<uint8_t> bench_corpus()
{
        std::vector<uint16_t> px((size_t)BENCH_WIDTH * BENCH_HEIGHT, px16(0, 0, 0, 0));
        for (int c = 0; c < BENCH_GLYPHS; c++)
        {
                for (int y = 0; y < BENCH_HEIGHT; y++)
                        for (int x = 0; x < 12; x++)
                                px[(size_t)y * BENCH_WIDTH + c * 16 + x] =
                                    px16(1, c & 31, (c * 3) & 31, (c * 7) & 31);
        }

        std::vector<uint8_t> v;
        put_header(v, 0, TGA_TRUECOLOR, 0, 0, 0, BENCH_WIDTH, BENCH_HEIGHT, 16, 0x20);
        for (uint16_t p : px)
                put_u16(v, p);
        return v;
}

extern "C" long bench_font_materialize(uint8_t *out, size_t cap);
extern "C" long bench_font_materialize(uint8_t *out, size_t cap)
{
        std::vector<uint8_t> v = bench_corpus();
        if (v.size() > cap)
                return -1;
        memcpy(out, v.data(), v.size());
        return (long)v.size();
}

extern "C" uint64_t bench_font_parse(const uint8_t *data, size_t len);
extern "C" uint64_t bench_font_parse(const uint8_t *data, size_t len)
{
        g_files.clear();
        g_files["Bench.tga"] = std::vector<uint8_t>(data, data + len);
        g_loads = 0;
        g_font_tga_error = 0;
        g_font_file_missing = false;

        uint64_t sum;
        try
        {
                Font3DDataClass font("Bench.tga");
                sum = font_checksum(font);
        }
        catch (VerdictStop &)
        {
                sum = 0; // unreachable: the corpus is a clean strike
        }
        return sum;
}
